`SELECT project_id, parse_error, parse_failed_at, CASE WHEN json_type(parser_context, '$.mycoParserFailure') = 'object' THEN json_extract(parser_context, '$.mycoParserFailure') END AS diagnostic FROM transcripts INDEXED BY idx_transcripts_backlog
                WHERE parsed_offset < size AND parse_error IS NOT NULL AND parse_error <> '${AWAITING_BYTES}' AND NOT (${RETRY_STOPPED}) AND parser_version >= ? AND NOT ${TOMBSTONED}
                  AND EXISTS (SELECT 1 FROM projects p WHERE p.project_id = transcripts.project_id AND p.archived_at IS NULL)`

`UPDATE member_credentials SET revoked_at = ?, revoked_by = ?
      WHERE machine_id = ? AND revoked_at IS NULL
        AND ${OWNER_CONTROL_CREDENTIAL_WRITE}
        AND ${memberWritePredicate('?', 'member_credentials.member_id')}
        AND EXISTS (SELECT 1 FROM machine_claims mc WHERE mc.machine_id = member_credentials.machine_id
          AND mc.member_id = member_credentials.member_id)`

`SELECT session_id AS sessionId, due_at AS observed FROM turn_cards c INDEXED BY idx_turn_cards_due
        WHERE project_id = ? AND c.${pending(now)} AND ${notInFlight(CARD_TASK, cardSubject, 'c.session_id')}
        ORDER BY due_at DESC LIMIT 1`

`SELECT session_id AS sessionId, eligible_at AS observed FROM learning_sessions l INDEXED BY idx_learning_eligible
        WHERE project_id = ? AND l.${eligible(now)} AND ${notInFlight(EXTRACTION_TASK, learningSubject, 'l.session_id')}
        ORDER BY eligible_at DESC LIMIT 1`

`UPDATE session_prompts SET ${kept('preview')},${kept('text_chars')},${count('tools')},${count('replies')},${count('children')},
          ${count('plans')},${kept('input_hash')},${kept('input_chars')}
        FROM json_each(?) j WHERE project_id=? AND session_id=? AND generation=? AND prompt_id=json_extract(j.value,'$.id')`

`SELECT COUNT(*) n FROM turn_cards c WHERE c.project_id=? AND c.session_id=?
    AND NOT EXISTS (SELECT 1 FROM session_prompts p WHERE p.project_id=c.project_id AND p.session_id=c.session_id AND p.generation=${GENERATION}
      AND p.prompt_id=c.turn_key AND p.turn_key=p.prompt_id)`

`INSERT INTO events (${rawMaterial.insert.columns.join(',')})
      SELECT ${rawMaterial.insert.sql} WHERE ${admission.map((a) => a.sql).join(' AND ')}
      ON CONFLICT(project_id,event_id) DO NOTHING`

`INSERT INTO attachments (${merged.insert.columns.join(',')})
          SELECT ${merged.insert.sql} ${merged.insert.source!.sql} AND ${RAW_ROW_GATE}
          ON CONFLICT (project_id, attachment_id) DO NOTHING`

`INSERT INTO plans (${merged.insert.columns.join(', ')})
        SELECT ${merged.insert.sql} WHERE ${RAW_ROW_GATE}
        ON CONFLICT(project_id,plan_key) DO UPDATE SET ${merged.update.sql}`

`UPDATE tool_calls AS t SET ${mutation.update.sql}
      WHERE t.project_id = ? AND t.tool_call_id = ? AND t.session_id = ? AND ${gate.sql}
        AND ${changed.sql}
      RETURNING tool_call_id`

`INSERT OR IGNORE INTO fact_classes(project_id,table_name,record_id,session_id,class,classified_at)
      SELECT r.project_id,'${table}',r.${id},r.session_id,CASE WHEN ${legacyRowSql(table, 'r')} THEN 'legacy' ELSE 'unverified' END,${CLASSIFIED_AT_SQL}
      FROM ${table} r WHERE r.rowid>? AND r.rowid<=? AND (${legacyRowSql(table, 'r')} OR ${unverifiedRowSql('r')})`

`PRAGMA foreign_keys=ON;
   CREATE TABLE parent(project_id TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(project_id,id));
   CREATE TABLE required_child(project_id TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT NOT NULL,FOREIGN KEY(project_id,parent_id) REFERENCES parent(project_id,id));
   CREATE TABLE optional_child(project_id TEXT NOT NULL,id TEXT NOT NULL,parent_id TEXT,FOREIGN KEY(project_id,parent_id) REFERENCES parent(project_id,id))`
